# For each color, extend left-edge horizontal bars across the row; also extend aligned right edges across adjacent rows.
code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Identify the foreground and background colors.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = max(counts, key=counts.get)
    colors = [c for c in counts if c != bg]
    if not colors:
        return out
    # Process each non-background color independently.
    for color in colors:
        runs = {}
        for r, row in enumerate(grid):
            cols = [c for c, v in enumerate(row) if v == color]
            if not cols:
                continue
            # A line anchored at the left edge extends to the right boundary.
            if cols[0] == 0:
                end = 0
                while end + 1 < w and row[end + 1] == color:
                    end += 1
                for c in range(end + 1, w):
                    if out[r][c] == bg:
                        out[r][c] = 1
            # Record the rightmost contiguous run for paired, aligned bars.
            end = cols[-1]
            start = end
            while start > 0 and row[start - 1] == color:
                start -= 1
            runs[r] = (start, end)
        # If neighboring rows share a straight right edge, extend both rows
        # beyond that edge. This captures a multi-row bar with an irregular left side.
        for r in range(h - 1):
            if r in runs and r + 1 in runs:
                s1, e1 = runs[r]
                s2, e2 = runs[r + 1]
                if e1 == e2 and e1 < w - 1 and min(e1 - s1 + 1, e2 - s2 + 1) >= 2:
                    for rr in (r, r + 1):
                        for c in range(e1 + 1, w):
                            if out[rr][c] == bg:
                                out[rr][c] = 1
    return out
'''
